9		Version       int    `json:"version"`
10		Constraints   int    `json:"constraints"`
11		PublicInputs  int    `json:"public_inputs"`
12		PrivateInputs int    `json:"private_inputs"`
13		Frozen        bool   `json:"frozen"`
14		// Description is the human-readable description bound to this version.
15		Description string `json:"description"`
16	}
