18	// Job is one prove or verify attempt bound to one circuit version.
19	type Job struct {
20		ID       string `json:"id"`
21		Circuit  string `json:"circuit"`
22		Version  int    `json:"version"`
23		Kind     string `json:"kind"`
24		Attempt  int    `json:"attempt"`
25		Artifact string `json:"artifact"`
26		// CompiledHash optionally binds the job to the compiled artifact of the
27		// pinned circuit version. Empty means unbound; a non-empty value must
28		// equal that version's artifact hash exactly.
29		CompiledHash string `json:"compiled_hash,omitempty"`
30	}
31	
32	// Setup is a trusted setup record registered for one frozen circuit version.
33	type Setup struct {
34		Name    string `json:"name"`
35		Version int    `json:"version"`
36	}
37	
38	// Validate refuses to run a job against a moved or unfrozen circuit.
39	func Validate(circuit Circuit, job Job, trustedSetup bool) error {
40		if circuit.Name == "" || job.Circuit != circuit.Name {
41			return errInvalid("job references an unknown circuit")
42		}
43		if job.Version != circuit.Version {
44			return errInvalid("job pinned to a stale circuit version")
45		}
46		if !circuit.Frozen {
47			return errInvalid("circuit must be frozen before proving")
48		}
49		if job.Kind == "prove" && !trustedSetup {
50			return errInvalid("proving requires a recorded trusted setup")
51		}
52		if circuit.Constraints <= 0 {
53			return errInvalid("circuit has no constraints")
54		}
55		return nil
56	}
57	
58	// WitnessCost orders circuits by constraint load, largest first.
59	func WitnessCost(circuits []Circuit) []string {
60		sorted := append([]Circuit(nil), circuits...)
61		sort.Slice(sorted, func(i, j int) bool {
62			if sorted[i].Constraints == sorted[j].Constraints {
63				return sorted[i].Name < sorted[j].Name
64			}
65			return sorted[i].Constraints > sorted[j].Constraints
66		})
67		var names []string
68		for _, circuit := range sorted {
69			names = append(names, circuit.Name)
70		}
71		return names
72	}
