1	package zkcircuit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15	)
16	
17	// on-disk layout inside the data directory:
18	//
19	//	data.json    – the committed state (JSON envelope, atomically replaced)
20	//	data.json.tmp– staging file for the next commit (rename(2) target)
21	//	lock         – flock file serializing concurrent processes
22	//
23	// The envelope carries an explicit format version: files written by an
24	// incompatible future build are refused rather than silently migrated or
25	// overwritten.
26	const (
27		dirDataFile = "data.json"
28		dirTmpFile  = "data.json.tmp"
29		dirLockFile = "lock"
30	
31		// FormatVersion is the on-disk format this build writes and accepts.
32		FormatVersion = 1
33	)
34	
35	// envelope is the persisted state container.
36	//
37	// Circuits are kept as raw JSON during decoding so persistCircuit's strict
38	// UnmarshalJSON — rather than encoding/json's silent zero-value filling —
39	// decides what a committed circuit record may look like. UnmarshalJSON first
40	// walks the token stream (scanEnvelopeDuplicates) and rejects a repeated
41	// object key anywhere encoding/json would otherwise keep the last value.
42	type envelope struct {
43		Format    int               `json:"format"`
44		Circuits  []persistCircuit  `json:"circuits"`
45		Setups    []persistSetup    `json:"setups"`
46		Jobs      []persistJob      `json:"jobs"`
47		Artifacts []persistArtifact `json:"artifacts,omitempty"`
48	}
49	
50	// envelopeWire is the decoding-only shape: circuit records arrive raw so
51	// their own strict decoder can require every field explicitly.
52	type envelopeWire struct {
53		Format    int               `json:"format"`
54		Circuits  []json.RawMessage `json:"circuits"`
55		Setups    []persistSetup    `json:"setups"`
56		Jobs      []persistJob      `json:"jobs"`
57		Artifacts []persistArtifact `json:"artifacts,omitempty"`
58	}
59	
60	func (e *envelope) UnmarshalJSON(raw []byte) error {
61		// Reject repeated keys before decoding: encoding/json silently keeps the
62		// last value of a duplicate. The walk is layered so a repeated field is
63		// attributed to the record it belongs to (a duplicate "frozen" inside
64		// circuit #3, not a generic envelope complaint).
65		if err := scanEnvelopeDuplicates(raw); err != nil {
66			return err
67		}
68		var wire envelopeWire
69		if err := json.Unmarshal(raw, &wire); err != nil {
70			var se StoreError
71			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
72				return err // an inner record decoder already named the problem
73			}
74			return corruptf("data file envelope is not valid JSON: %v", err)
75		}
76		e.Format = wire.Format
77		e.Setups = wire.Setups
78		e.Jobs = wire.Jobs
79		e.Artifacts = wire.Artifacts
80		if wire.Circuits == nil {
81			e.Circuits = nil
82		} else {
83			e.Circuits = make([]persistCircuit, len(wire.Circuits))
84		}
85		for i, craw := range wire.Circuits {
86			var record persistCircuit
87			if err := json.Unmarshal(craw, &record); err != nil {
88				var se StoreError
89				if errors.As(err, &se) {
90					// Re-tag as one corruption error carrying the record index,
91					// so the detail survives errors.As unwrapping in loadLocked.
92					return StoreError{Kind: ErrDataCorrupt.Kind,
93						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
94				}
95				return corruptf("circuit record #%d: %v", i+1, err)
96			}
97			e.Circuits[i] = record
98		}
99		return nil
100	}
101	
102	// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
103	// repeated object key. Circuit records are scanned one level deep only —
104	// their top-level fields are checked here (with the record's 1-based index
105	// reported), while values such as the constraint definition are skipped and
106	// left to their own strict decoders. Every other envelope member is scanned
107	// recursively so a duplicated key anywhere in committed data fails the read
108	// instead of silently resolving to its last value.
109	func scanEnvelopeDuplicates(raw []byte) error {
110		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
111		dec.UseNumber()
112		open, err := dec.Token()
113		if err != nil || open != json.Delim('{') {
114			return corruptf("data file envelope must be a JSON object")
115		}
116		seenTop := make(map[string]bool)
117		for dec.More() {
118			keyTok, err := dec.Token()
119			if err != nil {
120				return corruptf("data file envelope is not valid JSON: %v", err)
121			}
122			key, ok := keyTok.(string)
123			if !ok {
124				return corruptf("data file envelope is not valid JSON")
125			}
126			if seenTop[key] {
127				return corruptf("data file envelope contains duplicate field %q", key)
128			}
129			seenTop[key] = true
130			if key == "circuits" {
131				if err := scanCircuitArrayDuplicates(dec); err != nil {
132					return err
133				}
134				continue
135			}
136			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
137				return err
138			}
139		}
140		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
141			return corruptf("data file envelope is not valid JSON")
142		}
143		if _, err := dec.Token(); err != io.EOF {
144			return corruptf("data file envelope is not valid JSON: trailing data after the object")
145		}
146		return nil
147	}
