149	// scanCircuitArrayDuplicates consumes one "circuits" value positioned at its
150	// opening bracket and checks only each record's own top-level keys. A null
151	// array stays the pre-existing "no records" reading.
152	func scanCircuitArrayDuplicates(dec *json.Decoder) error {
153		tok, err := dec.Token()
154		if err != nil {
155			return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
156		}
157		if tok == nil { // null: json.Unmarshal would produce no records
158			return nil
159		}
160		if tok != json.Delim('[') {
161			return corruptf("data file envelope field \"circuits\" must be an array")
162		}
163		index := 0
164		for dec.More() {
165			index++
166			what := fmt.Sprintf("circuit record #%d", index)
167			open, err := dec.Token()
168			if err != nil {
169				return corruptf("%s is not valid JSON: %v", what, err)
170			}
171			if open == nil {
172				return corruptf("%s must be a JSON object, not null", what)
173			}
174			if open != json.Delim('{') {
175				return corruptf("%s must be a JSON object", what)
176			}
177			seen := make(map[string]bool)
178			for dec.More() {
179				keyTok, err := dec.Token()
180				if err != nil {
181					return corruptf("%s is not valid JSON: %v", what, err)
182				}
183				key, ok := keyTok.(string)
184				if !ok {
185					return corruptf("%s is not valid JSON", what)
186				}
187				if seen[key] {
188					return corruptf("%s contains duplicate field %q", what, key)
189				}
190				seen[key] = true
191				// Skip the whole value without descending: nested objects
192				// (definition) own their own strict duplicate checks.
193				var skip json.RawMessage
194				if err := dec.Decode(&skip); err != nil {
195					return corruptf("%s is not valid JSON: %v", what, err)
196				}
197			}
198			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
199				return corruptf("%s is not valid JSON", what)
200			}
201		}
202		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
203			return corruptf("data file envelope field \"circuits\" is not valid JSON")
204		}
205		return nil
206	}
207	
208	// skipValueWithDupKeys consumes one JSON value positioned at its first token,
209	// recursively rejecting duplicate object keys.
210	func skipValueWithDupKeys(dec *json.Decoder, what string) error {
211		tok, err := dec.Token()
212		if err != nil {
213			return corruptf("%s is not valid JSON: %v", what, err)
214		}
215		delim, ok := tok.(json.Delim)
216		if !ok {
217			return nil // scalar (including null)
218		}
219		switch delim {
220		case '{':
221			seen := make(map[string]bool)
222			for dec.More() {
223				keyTok, err := dec.Token()
224				if err != nil {
225					return corruptf("%s is not valid JSON: %v", what, err)
226				}
227				key, ok := keyTok.(string)
228				if !ok {
229					return corruptf("%s is not valid JSON", what)
230				}
231				if seen[key] {
232					return corruptf("%s contains duplicate field %q", what, key)
233				}
234				seen[key] = true
235				if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
236					return err
237				}
238			}
239			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
240				return corruptf("%s is not valid JSON", what)
241			}
242		case '[':
243			index := 0
244			for dec.More() {
245				index++
246				if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
247					return err
248				}
249			}
250			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
251				return corruptf("%s is not valid JSON", what)
252			}
253		}
254		return nil
255	}
