298	// Strict decoding of committed circuit records.
299	//
300	// A circuit record in data.json must name each of name, version, constraints,
301	// public_inputs, private_inputs, frozen and description exactly once, with
302	// the exact JSON type the writer emits (string / integer / integer / integer
303	// / integer / boolean / string). A missing key, a null, a wrong type or a
304	// repeated key is data corruption and refuses the whole directory read: a
305	// missing or null frozen flag must not silently read as false (turning a
306	// frozen version back into an editable draft), and a repeated key must not
307	// resolve to its last value. An explicit 0, false or "" is an ordinary value
308	// and stays legal. The definition member remains the one optional field: it
309	// may be absent or null (the legacy counts-only state); when present it goes
310	// through the strict persistDefinition decoder.
311	//
312	// Only shape is judged here. The domain rules (non-blank name, positive
313	// version and constraint count, non-negative input counts) keep being
314	// re-checked by validateEnvelope.
315	
316	var persistCircuitFields = []string{
317		"name", "version", "constraints", "public_inputs", "private_inputs",
318		"frozen", "description", "definition",
319	}
320	
321	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
322		const what = "stored circuit record"
323		if string(bytes.TrimSpace(raw)) == "null" {
324			return corruptf("%s must be a JSON object, not null", what)
325		}
326		members, err := strictCircuitObject(raw, what)
327		if err != nil {
328			return err
329		}
330	
331		var out persistCircuit
332	
333		requireString := func(key string, dst *string) error {
334			r, err := requireMember(members, key, what)
335			if err != nil {
336				return asCorrupt(err)
337			}
338			v, err := decodeJSONString(r, what+" field "+strconv.Quote(key))
339			if err != nil {
340				return asCorrupt(err)
341			}
342			*dst = v
343			return nil
344		}
345		requireInt := func(key string, dst *int) error {
346			r, err := requireMember(members, key, what)
347			if err != nil {
348				return asCorrupt(err)
349			}
350			v, err := decodeJSONInt(r, what+" field "+strconv.Quote(key))
351			if err != nil {
352				return asCorrupt(err)
353			}
354			*dst = v
355			return nil
356		}
357	
358		if err := requireString("name", &out.Name); err != nil {
359			return err
360		}
361		if err := requireInt("version", &out.Version); err != nil {
362			return err
363		}
364		if err := requireInt("constraints", &out.Constraints); err != nil {
365			return err
366		}
367		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
368			return err
369		}
370		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
371			return err
372		}
373		frozenRaw, err := requireMember(members, "frozen", what)
374		if err != nil {
375			return asCorrupt(err)
376		}
377		out.Frozen, err = decodeJSONBool(frozenRaw, what+" field "+strconv.Quote("frozen"))
378		if err != nil {
379			return asCorrupt(err)
380		}
381		if err := requireString("description", &out.Description); err != nil {
382			return err
383		}
384	
385		// definition is the only optional member: absent or null both mean the
386		// counts-only legacy state.
387		if defRaw, present := members["definition"]; present {
388			if string(bytes.TrimSpace(defRaw)) != "null" {
389				var def persistDefinition
390				if err := json.Unmarshal(defRaw, &def); err != nil {
391					var se StoreError
392					if errors.As(err, &se) {
393						return err // already reported as data corruption
394					}
395					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
396				}
397				out.Definition = &def
398			}
399		}
400	
401		*c = out
402		return nil
403	}
