473	// Store is a persistent workbench backed by one local data directory.
474	//
475	// All operations are safe for concurrent use by multiple goroutines and by
476	// several processes pointed at the same directory: an in-process mutex plus a
477	// process-shared flock serialize commits, and every commit is an atomic
478	// temp-file/fsync/rename replacement. Open the directory with Open and call
479	// Close when done.
480	type Store struct {
481		dir  string
482		mu   sync.Mutex
483		lock *os.File
484	
485		data envelope
486	}
487	
488	// Open opens (creating if needed) the workbench data in dir. If the
489	// directory does not exist it is created. Existing committed data is loaded
490	// and fully validated before Open returns; on a corrupt, truncated or
491	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
492	// leaves every file in the directory untouched.
493	func Open(dir string) (*Store, error) {
494		if dir == "" {
495			return nil, invalidf("data directory must not be empty")
496		}
497		if err := os.MkdirAll(dir, 0o755); err != nil {
498			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
499		}
500		lockPath := filepath.Join(dir, dirLockFile)
501		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
502		if err != nil {
503			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
504		}
505		// Serialize against other processes while we read / validate.
506		if err := lockExclusive(lock); err != nil {
507			lock.Close()
508			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
509		}
510	
511		s := &Store{dir: dir, lock: lock}
512		if err := s.loadLocked(); err != nil {
513			unlockLock(lock)
514			lock.Close()
515			return nil, err
516		}
517		// The lock is taken again per operation; holding it for the store's
518		// lifetime would forbid two open handles on one directory.
519		if err := unlockLock(lock); err != nil {
520			lock.Close()
521			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
522		}
523		return s, nil
524	}
525	
526	// Close releases the directory lock. It does not discard committed data.
527	func (s *Store) Close() error {
528		s.mu.Lock()
529		defer s.mu.Unlock()
530		if s.lock == nil {
531			return nil
532		}
533		var first error
534		if err := unlockLock(s.lock); err != nil {
535			first = err
536		}
537		if err := s.lock.Close(); err != nil && first == nil {
538			first = err
539		}
540		s.lock = nil
541		return first
542	}
543	
544	// Dir reports the data directory backing the store.
545	func (s *Store) Dir() string { return s.dir }
546	
547	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
548	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
549	
550	// loadLocked reads and validates the committed file. Caller must hold the
551	// exclusive flock; the in-process mutex is taken by the public Open path.
552	func (s *Store) loadLocked() error {
553		raw, err := os.ReadFile(s.dataPath())
554		if errors.Is(err, os.ErrNotExist) {
555			s.data = envelope{Format: FormatVersion}
556			return nil
557		}
558		if err != nil {
559			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
560		}
561		if len(strings.TrimSpace(string(raw))) == 0 {
562			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
563		}
564	
565		var env envelope
566		if err := json.Unmarshal(raw, &env); err != nil {
567			// Shape failures surfaced by the persisted-definition decoders are
568			// integrity failures, not JSON syntax errors; report their detail
569			// instead of the generic "not valid JSON" wording.
570			var se StoreError
571			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
572				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
573			}
574			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
575		}
576		if env.Format == 0 {
577			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
578		}
579		if env.Format != FormatVersion {
580			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
581				s.dataPath(), env.Format, FormatVersion)
582		}
583		if err := validateEnvelope(env); err != nil {
584			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
585		}
586		s.data = env
587		return nil
588	}
589	
590	// commitLocked writes the pending state atomically: temp file → fsync →
591	// rename → fsync directory. Caller must hold both the in-process mutex and
592	// the exclusive flock; all in-memory mutations must already have happened and
593	// been rule-checked, so a failure here occurs before any success is reported.
594	func (s *Store) commitLocked() error {
595		s.data.Format = FormatVersion
596		// Stable output: records are stored sorted so files are deterministic.
597		sortEnvelope(&s.data)
598	
599		payload, err := json.MarshalIndent(&s.data, "", "  ")
600		if err != nil {
601			return fmt.Errorf("cannot encode data: %w", err)
602		}
603		payload = append(payload, '\n')
604	
605		tmp := s.tmpPath()
606		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
607		if err != nil {
608			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
609		}
610		if _, err := f.Write(payload); err != nil {
611			f.Close()
612			os.Remove(tmp)
613			return fmt.Errorf("cannot write staged data: %w", err)
614		}
615		if err := f.Sync(); err != nil {
616			f.Close()
617			os.Remove(tmp)
618			return fmt.Errorf("cannot flush staged data: %w", err)
619		}
620		if err := f.Close(); err != nil {
621			os.Remove(tmp)
622			return fmt.Errorf("cannot finish staged data: %w", err)
623		}
624		if err := os.Rename(tmp, s.dataPath()); err != nil {
625			os.Remove(tmp)
626			return fmt.Errorf("cannot commit data file: %w", err)
627		}
628		if err := syncDir(s.dir); err != nil {
629			// The rename already happened; lack of dir fsync only weakens crash
630			// durability, never correctness of what is visible now.
631			return nil
632		}
633		return nil
634	}
635	
636	// withLock runs fn under the in-process mutex and an exclusive flock, then
637	// atomically commits when fn requests it. The on-disk state is re-read after
638	// acquiring the lock, so concurrent commits from another process or another
639	// handle are always observed. Operations validate before mutating; a rejected
640	// operation (commit=false or an error) writes nothing and leaves committed
641	// state unchanged.
642	func (s *Store) withLock(fn func() (commit bool, err error)) error {
643		s.mu.Lock()
644		defer s.mu.Unlock()
645		if s.lock == nil {
646			return invalidf("store is closed")
647		}
648		if err := lockExclusive(s.lock); err != nil {
649			return fmt.Errorf("cannot lock data directory: %w", err)
650		}
651		defer unlockLock(s.lock)
652	
653		if err := s.loadLocked(); err != nil {
654			return err
655		}
656		commit, err := fn()
657		if err != nil {
658			return err
659		}
660		if !commit {
661			return nil
662		}
663		return s.commitLocked()
664	}
665	
666	// withLockRead runs fn under a shared flock over freshly reloaded state.
667	func (s *Store) withLockRead(fn func() error) error {
668		s.mu.Lock()
669		defer s.mu.Unlock()
670		if s.lock == nil {
671			return invalidf("store is closed")
672		}
673		if err := lockShared(s.lock); err != nil {
674			return fmt.Errorf("cannot lock data directory: %w", err)
675		}
676		defer unlockLock(s.lock)
677		if err := s.loadLocked(); err != nil {
678			return err
679		}
680		return fn()
681	}
