1	package zkcircuit
2	
3	import (
4		"sort"
5		"strings"
6	)
7	
8	// This file holds the domain operations of the persistent workbench. Every
9	// mutating operation validates its request before touching state, runs under
10	// the shared process lock and either commits one complete new state or
11	// commits nothing.
12	
13	// CreateCircuit creates a draft circuit version identified by Name+Version.
14	//
15	// The name must be non-empty and not only whitespace; Version must be
16	// positive; Constraints must be positive; the input counts must not be
17	// negative. Creating an already-existing version is idempotent when the
18	// description is identical (the stored record is returned unchanged); a
19	// differing description is reported as ErrConflict. Nothing about an
20	// existing version — frozen or not — is ever replaced by Create.
21	func (s *Store) CreateCircuit(c Circuit) (Circuit, error) {
22		if err := validateCircuitKey(c.Name, c.Version); err != nil {
23			return Circuit{}, err
24		}
25		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
26			return Circuit{}, err
27		}
28	
29		var result Circuit
30		err := s.withLock(func() (bool, error) {
31			if existing := findCircuit(s.data.Circuits, c.Name, c.Version); existing != nil {
32				if existing.Description != c.Description {
33					return false, conflictf("circuit %q version %d already exists with a different description", c.Name, c.Version)
34				}
35				result = circuitFromPersist(*existing)
36				return false, nil
37			}
38			record := persistCircuit{
39				Name: c.Name, Version: c.Version,
40				Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
41				Frozen: false, Description: c.Description,
42			}
43			s.data.Circuits = append(s.data.Circuits, record)
44			result = circuitFromPersist(record)
45			return true, nil
46		})
47		return result, err
48	}
49	
50	// UpdateCircuit modifies a draft circuit version. It must target an existing,
51	// unfrozen version explicitly: unknown versions yield ErrNotFound and frozen
52	// versions yield ErrFrozen. On success the counts and description are
53	// replaced as one atomic change; partial updates can never be observed.
54	//
55	// This is the whole-record replacement entry point: the three counts and the
56	// description carried by c override the stored record outright (zero values
57	// included). Field-by-field editing with omitted-field preservation lives in
58	// UpdateCircuitPartial; both entry points run the same draft-update rules
59	// through the circuitMutation helpers below.
60	func (s *Store) UpdateCircuit(c Circuit) (Circuit, error) {
61		if err := validateCircuitKey(c.Name, c.Version); err != nil {
62			return Circuit{}, err
63		}
64		mutation := circuitMutation{
65			Constraints:   c.Constraints,
66			PublicInputs:  c.PublicInputs,
67			PrivateInputs: c.PrivateInputs,
68			Description:   c.Description,
69		}
70		// Whole replacement judges the supplied counts before the target is
71		// looked up, so an illegal replacement reports invalid argument even for
72		// unknown or frozen versions.
73		if err := validateMutationCounts(mutation); err != nil {
74			return Circuit{}, err
75		}
76	
77		var result Circuit
78		err := s.withLock(func() (bool, error) {
79			existing := findCircuit(s.data.Circuits, c.Name, c.Version)
80			if existing == nil {
81				return false, notFoundf("circuit %q version %d does not exist", c.Name, c.Version)
82			}
83			if existing.Frozen {
84				return false, frozenf("circuit %q version %d is frozen and its description cannot be modified", c.Name, c.Version)
85			}
86			if err := validateMutationDefinition(*existing, mutation); err != nil {
87				return false, err
88			}
89			result = applyCircuitMutation(existing, mutation)
90			return true, nil
91		})
92		return result, err
93	}
94	
95	// PartialCircuit carries optional replacement fields for one draft circuit
96	// version. A nil pointer leaves the stored field untouched; a non-nil pointer
97	// — even to zero or to the empty string — replaces the field. This lets a
98	// caller change exactly one field without restating the others.
99	type PartialCircuit struct {
100		Constraints   *int
101		PublicInputs  *int
102		PrivateInputs *int
103		Description   *string
104	}
105	
106	// UpdateCircuitPartial modifies selected fields of a draft circuit version.
107	//
108	// Only fields present in patch are changed; omitted fields keep their stored
109	// values. A non-nil pointer still replaces its field even when it points at
110	// zero or the empty string (explicit zero clears an input count, an empty
111	// string clears the description). The whole merged result is validated
112	// before anything is committed: constraints must stay positive and input
113	// counts non-negative, and when a constraint definition is already imported
114	// the merged counts must keep it legal (exact constraint count, every
115	// referenced wire inside the new input layout). Any rejected field refuses
116	// the entire change — description, counts and the stored definition all
117	// remain as they were. The merged result is checked through the same
118	// circuitMutation helpers as UpdateCircuit's whole replacement.
119	//
120	// Existence and frozen state are settled before the merged counts are
121	// judged: unknown versions yield ErrNotFound and frozen versions
122	// ErrFrozen, even when the patch carries an illegal count or no field at
123	// all. A patch that provides no modifiable field at all returns the stored
124	// record unchanged and commits nothing (no new version, no data write).
125	func (s *Store) UpdateCircuitPartial(name string, version int, patch PartialCircuit) (Circuit, error) {
126		if err := validateCircuitKey(name, version); err != nil {
127			return Circuit{}, err
128		}
129		hasField := patch.Constraints != nil || patch.PublicInputs != nil ||
130			patch.PrivateInputs != nil || patch.Description != nil
131	
132		var result Circuit
133		err := s.withLock(func() (bool, error) {
134			existing := findCircuit(s.data.Circuits, name, version)
135			if existing == nil {
136				return false, notFoundf("circuit %q version %d does not exist", name, version)
137			}
138			if existing.Frozen {
139				return false, frozenf("circuit %q version %d is frozen and cannot be modified", name, version)
140			}
141			// Merge the provided fields over the stored record; omitted fields
142			// keep their committed values, so the merged counts are always the
143			// complete result this modification would leave behind.
144			mutation := circuitMutation{
145				Constraints:   existing.Constraints,
146				PublicInputs:  existing.PublicInputs,
147				PrivateInputs: existing.PrivateInputs,
148				Description:   existing.Description,
149			}
150			if patch.Constraints != nil {
151				mutation.Constraints = *patch.Constraints
152			}
153			if patch.PublicInputs != nil {
154				mutation.PublicInputs = *patch.PublicInputs
155			}
156			if patch.PrivateInputs != nil {
157				mutation.PrivateInputs = *patch.PrivateInputs
158			}
159			if patch.Description != nil {
160				mutation.Description = *patch.Description
161			}
162			if err := validateMutationCounts(mutation); err != nil {
163				return false, err
164			}
165			if err := validateMutationDefinition(*existing, mutation); err != nil {
166				return false, err
167			}
168			// No modifiable field was provided: return the stored record without
169			// committing anything.
170			if !hasField {
171				result = circuitFromPersist(*existing)
172				return false, nil
173			}
174			result = applyCircuitMutation(existing, mutation)
175			return true, nil
176		})
177		return result, err
178	}
179	
180	// --- draft update internals -----------------------------------------------
181	//
182	// circuitMutation is the complete set of updatable draft fields one
183	// modification would leave committed: the three counts and the description.
184	// Both public update entry points resolve their request into this type —
185	// UpdateCircuit takes all four values from the request, UpdateCircuitPartial
186	// merges request fields over the stored record — and then share the same
187	// count rules, imported-definition compatibility check and commit, so the
188	// two usages can never drift apart. A mutation never replaces the stored
189	// constraint definition; it is only checked against it.
190	type circuitMutation struct {
191		Constraints   int
192		PublicInputs  int
193		PrivateInputs int
194		Description   string
195	}
196	
197	// validateMutationCounts holds the basic count rules for any draft update:
198	// constraints must be greater than zero and both input counts must not be
199	// negative. The rules are judged on the mutation's complete resulting
200	// counts, not on the supplied fields alone.
201	func validateMutationCounts(m circuitMutation) error {
202		return validateCounts(m.Constraints, m.PublicInputs, m.PrivateInputs)
203	}
204	
205	// validateMutationDefinition holds the rule shared with imported
206	// definitions: when the version already has one, the mutation's complete
207	// resulting counts must keep it legal — exactly as many constraints as the
208	// definition and every referenced wire inside the resulting public/private
209	// input layout. An unreadable stored definition is reported as data
210	// corruption. A version without a definition imposes no extra rule.
211	func validateMutationDefinition(existing persistCircuit, m circuitMutation) error {
212		if existing.Definition == nil {
213			return nil
214		}
215		parsed, perr := definitionFromPersist(*existing.Definition, existing.PublicInputs, existing.PrivateInputs)
216		if perr != nil {
217			return corruptf("stored definition for %q v%d is unreadable: %v", existing.Name, existing.Version, perr)
218		}
219		if !parsed.compatibleWith(m.Constraints, m.PublicInputs, m.PrivateInputs) {
220			return invalidf("update rejected: it would make the imported constraint definition illegal (constraint count or wire layout mismatch); the whole change is refused")
221		}
222		return nil
223	}
224	
225	// applyCircuitMutation commits a validated mutation onto the stored draft
226	// record, overwriting the three counts and the description together. The
227	// name, version, frozen flag and imported definition are never touched. The
228	// caller is responsible for all validation and for holding the store lock.
229	func applyCircuitMutation(existing *persistCircuit, m circuitMutation) Circuit {
230		existing.Constraints = m.Constraints
231		existing.PublicInputs = m.PublicInputs
232		existing.PrivateInputs = m.PrivateInputs
233		existing.Description = m.Description
234		return circuitFromPersist(*existing)
235	}
236	
237	// FreezeCircuit freezes a circuit version. Unknown versions yield
238	// ErrNotFound. Freezing an already-frozen version returns that version
239	// unchanged (idempotent). Once frozen, name, version and the three counts
240	// can never change again.
241	func (s *Store) FreezeCircuit(name string, version int) (Circuit, error) {
242		if err := validateCircuitKey(name, version); err != nil {
243			return Circuit{}, err
244		}
245	
246		var result Circuit
247		err := s.withLock(func() (bool, error) {
248			existing := findCircuit(s.data.Circuits, name, version)
249			if existing == nil {
250				return false, notFoundf("circuit %q version %d does not exist", name, version)
251			}
252			if existing.Frozen {
253				result = circuitFromPersist(*existing)
254				return false, nil
255			}
256			existing.Frozen = true
257			result = circuitFromPersist(*existing)
258			return true, nil
259		})
260		return result, err
261	}
262	
263	// CopyCircuit creates a new draft version of a circuit name by copying a
264	// frozen source version. The target version must be a positive integer
265	// different from the source version; it need not be consecutive or greater.
266	//
267	// The copy carries over the source's description, constraint count, public
268	// and private input counts, and — when the source has one — its complete
269	// constraint definition (modulus, constraint order and wire layout). A
270	// counts-only source produces a counts-only target with no definition. The
271	// new draft is fully independent: updating, re-importing or freezing it
272	// never touches the source, and the source's compiled artifacts, trusted
273	// setup and registered jobs are never copied or bound to the target. The
274	// target must register its own setup and compile its own artifact after
275	// freezing; the source's hash cannot satisfy the target's input checks or
276	// job bindings.
277	//
278	// Copying is idempotent: if the target already exists as a draft whose
279	// description, counts and definition are semantically equal to the source,
280	// the stored target is returned unchanged and nothing is written. A frozen
281	// target or a target whose description, counts or definition has changed
282	// yields ErrConflict. An unknown source yields ErrNotFound and an unfrozen
283	// source ErrNotFrozen; the source is always checked before the target.
284	func (s *Store) CopyCircuit(name string, version, toVersion int) (Circuit, error) {
285		if err := validateCircuitKey(name, version); err != nil {
286			return Circuit{}, err
287		}
288		if err := validateCircuitKey(name, toVersion); err != nil {
289			return Circuit{}, err
290		}
291		if version == toVersion {
292			return Circuit{}, invalidf("source and target version must differ for circuit %q", name)
293		}
294	
295		var result Circuit
296		err := s.withLock(func() (bool, error) {
297			source := findCircuit(s.data.Circuits, name, version)
298			if source == nil {
299				return false, notFoundf("circuit %q version %d does not exist", name, version)
300			}
301			if !source.Frozen {
302				return false, notFrozenf("circuit %q version %d must be frozen before it can be copied as a new draft", name, version)
303			}
304			target := findCircuit(s.data.Circuits, name, toVersion)
305			if target != nil {
306				if target.Frozen {
307					return false, conflictf("circuit %q version %d already exists and is frozen", name, toVersion)
308				}
309				if !circuitCopyMatches(*source, *target) {
310					return false, conflictf("circuit %q version %d already exists with content that differs from the source", name, toVersion)
311				}
312				result = circuitFromPersist(*target)
313				return false, nil
314			}
315			record := persistCircuit{
316				Name: name, Version: toVersion,
317				Constraints: source.Constraints, PublicInputs: source.PublicInputs, PrivateInputs: source.PrivateInputs,
318				Frozen: false, Description: source.Description,
319			}
320			if source.Definition != nil {
321				def := *source.Definition
322				record.Definition = &def
323			}
324			s.data.Circuits = append(s.data.Circuits, record)
325			result = circuitFromPersist(record)
326			return true, nil
327		})
328		return result, err
329	}
330	
331	// RecordSetup records a trusted setup for one frozen circuit version. The
332	// record belongs exclusively to that name+version. Unknown versions yield
333	// ErrNotFound; non-frozen versions yield ErrNotFrozen. Re-registering a
334	// setup for the same version is idempotent and adds no duplicate record.
335	func (s *Store) RecordSetup(name string, version int) (Setup, error) {
336		if err := validateCircuitKey(name, version); err != nil {
337			return Setup{}, err
338		}
339	
340		var result Setup
341		err := s.withLock(func() (bool, error) {
342			circuit := findCircuit(s.data.Circuits, name, version)
343			if circuit == nil {
344				return false, notFoundf("circuit %q version %d does not exist", name, version)
345			}
346			if !circuit.Frozen {
347				return false, notFrozenf("circuit %q version %d must be frozen before its trusted setup is recorded", name, version)
348			}
349			if existing := findSetup(s.data.Setups, name, version); existing != nil {
350				result = setupFromPersist(*existing)
351				return false, nil
352			}
353			record := persistSetup{Name: name, Version: version}
354			s.data.Setups = append(s.data.Setups, record)
355			result = setupFromPersist(record)
356			return true, nil
357		})
358		return result, err
359	}
360	
361	// SubmitJob accepts and stores a prove job. Only kind "prove" is accepted;
362	// no proving computation runs, the accepted request alone is persisted.
363	//
364	// The job id must be non-empty and not only whitespace, circuit name and
365	// version must be explicit and Attempt must be positive. Failure reasons are
366	// distinguishable: ErrNotFound (version unknown), ErrNotFrozen (version is
367	// still a draft) and ErrSetupMissing (no trusted setup for that version). A
368	// refused submission leaves no job behind.
369	//
370	// A non-empty CompiledHash additionally binds the job to the pinned
371	// version's compiled artifact, matched as the exact string: a version with
372	// no compiled artifact yields ErrArtifactMissing and a hash that differs
373	// from that artifact's hash yields ErrArtifactMismatch. Artifacts of other
374	// names or versions never satisfy the binding. An empty CompiledHash leaves
375	// the job unbound and keeps the register-only behavior.
376	//
377	// Resubmitting the same id with the same request — including the same
378	// optional hash — returns the stored job; the same id with different content
379	// yields ErrConflict, reported before any artifact check of the new request.
380	// A stored job stays pinned to the version submitted, regardless of circuit
381	// versions added later.
382	func (s *Store) SubmitJob(job Job) (Job, error) {
383		if strings.TrimSpace(job.ID) == "" {
384			return Job{}, invalidf("job id must be non-empty and not only whitespace")
385		}
386		if strings.TrimSpace(job.Circuit) == "" {
387			return Job{}, invalidf("job %q must name a circuit", job.ID)
388		}
389		if job.Version <= 0 {
390			return Job{}, invalidf("job %q must pin a positive circuit version", job.ID)
391		}
392		if job.Attempt <= 0 {
393			return Job{}, invalidf("job %q attempt must be a positive integer", job.ID)
394		}
395		if job.Kind != "prove" {
396			return Job{}, StoreError{Kind: ErrUnsupportedKind.Kind,
397				Detail: "job " + job.ID + " has unsupported kind " + job.Kind + "; only \"prove\" jobs are accepted"}
398		}
399	
400		var result Job
401		err := s.withLock(func() (bool, error) {
402			if existing := findJob(s.data.Jobs, job.ID); existing != nil {
403				if !sameJobRequest(*existing, job) {
404					return false, conflictf("job %q already exists with a different request", job.ID)
405				}
406				result = jobFromPersist(*existing)
407				return false, nil
408			}
409			circuit := findCircuit(s.data.Circuits, job.Circuit, job.Version)
410			if circuit == nil {
411				return false, notFoundf("job %q references unknown circuit %q version %d", job.ID, job.Circuit, job.Version)
412			}
413			if !circuit.Frozen {
414				return false, notFrozenf("job %q references circuit %q version %d which is not frozen", job.ID, job.Circuit, job.Version)
415			}
416			if findSetup(s.data.Setups, job.Circuit, job.Version) == nil {
417				return false, setupMissingf("job %q references frozen circuit %q version %d which has no recorded trusted setup",
418					job.ID, job.Circuit, job.Version)
419			}
420			if job.CompiledHash != "" {
421				artifact := findArtifact(s.data.Artifacts, job.Circuit, job.Version)
422				if artifact == nil {
423					return false, artifactMissingf("job %q references circuit %q version %d which has no compiled artifact",
424						job.ID, job.Circuit, job.Version)
425				}
426				if artifact.Hash != job.CompiledHash {
427					return false, artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
428						job.CompiledHash, job.Circuit, job.Version, artifact.Hash)
429				}
430			}
431			record := persistJob{
432				ID: job.ID, Circuit: job.Circuit, Version: job.Version,
433				Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
434				CompiledHash: job.CompiledHash,
435			}
436			s.data.Jobs = append(s.data.Jobs, record)
437			result = jobFromPersist(record)
438			return true, nil
439		})
440		return result, err
441	}
442	
443	// GetCircuit returns one circuit version, sorted-field populated exactly as
444	// stored. Unknown versions yield ErrNotFound.
445	func (s *Store) GetCircuit(name string, version int) (Circuit, error) {
446		if err := validateCircuitKey(name, version); err != nil {
447			return Circuit{}, err
448		}
449		var result Circuit
450		err := s.withLockRead(func() error {
451			existing := findCircuit(s.data.Circuits, name, version)
452			if existing == nil {
453				return notFoundf("circuit %q version %d does not exist", name, version)
454			}
455			result = circuitFromPersist(*existing)
456			return nil
457		})
458		return result, err
459	}
460	
461	// ListCircuits returns all stored circuit versions ordered by circuit name
462	// (lexicographically) and then by ascending version number.
463	func (s *Store) ListCircuits() ([]Circuit, error) {
464		var result []Circuit
465		err := s.withLockRead(func() error {
466			ordered := append([]persistCircuit(nil), s.data.Circuits...)
467			sort.Slice(ordered, func(i, j int) bool {
468				if ordered[i].Name != ordered[j].Name {
469					return ordered[i].Name < ordered[j].Name
470				}
471				return ordered[i].Version < ordered[j].Version
472			})
473			result = make([]Circuit, len(ordered))
474			for i, c := range ordered {
475				result[i] = circuitFromPersist(c)
476			}
477			return nil
478		})
479		return result, err
480	}
481	
482	// GetSetup reports whether a trusted setup is registered for the named
483	// frozen version. A missing record yields ErrNotFound.
484	func (s *Store) GetSetup(name string, version int) (Setup, bool, error) {
485		if err := validateCircuitKey(name, version); err != nil {
486			return Setup{}, false, err
487		}
488		var result Setup
489		found := false
490		err := s.withLockRead(func() error {
491			existing := findSetup(s.data.Setups, name, version)
492			if existing == nil {
493				return nil
494			}
495			result = setupFromPersist(*existing)
496			found = true
497			return nil
498		})
499		return result, found, err
500	}
501	
502	// GetJob returns one stored job by id. Unknown ids yield ErrNotFound.
503	func (s *Store) GetJob(id string) (Job, error) {
504		if strings.TrimSpace(id) == "" {
505			return Job{}, invalidf("job id must be non-empty and not only whitespace")
506		}
507		var result Job
508		err := s.withLockRead(func() error {
509			existing := findJob(s.data.Jobs, id)
510			if existing == nil {
511				return notFoundf("job %q does not exist", id)
512			}
513			result = jobFromPersist(*existing)
514			return nil
515		})
516		return result, err
517	}
518	
519	// ListJobs returns all accepted jobs ordered by job id lexicographically.
520	func (s *Store) ListJobs() ([]Job, error) {
521		var result []Job
522		err := s.withLockRead(func() error {
523			ordered := append([]persistJob(nil), s.data.Jobs...)
524			sort.Slice(ordered, func(i, j int) bool { return ordered[i].ID < ordered[j].ID })
525			result = make([]Job, len(ordered))
526			for i, j := range ordered {
527				result[i] = jobFromPersist(j)
528			}
529			return nil
530		})
531		return result, err
532	}
533	
534	// --- validation helpers ---------------------------------------------------
535	
536	func validateCircuitKey(name string, version int) error {
537		if strings.TrimSpace(name) == "" {
538			return invalidf("circuit name must be non-empty and not only whitespace")
539		}
540		if version <= 0 {
541			return invalidf("circuit %q version must be a positive integer, got %d", name, version)
542		}
543		return nil
544	}
545	
546	func validateCounts(constraints, publicInputs, privateInputs int) error {
547		if constraints <= 0 {
548			return invalidf("constraints must be greater than zero, got %d", constraints)
549		}
550		if publicInputs < 0 {
551			return invalidf("public input count must not be negative, got %d", publicInputs)
552		}
553		if privateInputs < 0 {
554			return invalidf("private input count must not be negative, got %d", privateInputs)
555		}
556		return nil
557	}
558	
559	// --- lookup / mapping helpers --------------------------------------------
560	
561	func findCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
562		for i := range cs {
563			if cs[i].Name == name && cs[i].Version == version {
564				return &cs[i]
565			}
566		}
567		return nil
568	}
569	
570	func findSetup(ps []persistSetup, name string, version int) *persistSetup {
571		for i := range ps {
572			if ps[i].Name == name && ps[i].Version == version {
573				return &ps[i]
574			}
575		}
576		return nil
577	}
578	
579	func findJob(js []persistJob, id string) *persistJob {
580		for i := range js {
581			if js[i].ID == id {
582				return &js[i]
583			}
584		}
585		return nil
586	}
587	
588	func sameJobRequest(stored persistJob, request Job) bool {
589		return stored.Circuit == request.Circuit &&
590			stored.Version == request.Version &&
591			stored.Kind == request.Kind &&
592			stored.Attempt == request.Attempt &&
593			stored.CompiledHash == request.CompiledHash
594	}
595	
596	func circuitFromPersist(c persistCircuit) Circuit {
597		return Circuit{
598			Name: c.Name, Version: c.Version,
599			Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
600			Frozen: c.Frozen, Description: c.Description,
601		}
602	}
603	
604	// circuitCopyMatches reports whether target is the same draft content that a
605	// copy of source would create: same description, same three counts and a
606	// semantically equal constraint definition. Definition equality follows the
607	// existing normalization semantics (terms merged per wire, coefficients
608	// reduced modulo p, zeros dropped, wires sorted ascending); a missing
609	// definition differs from a present one.
610	func circuitCopyMatches(source, target persistCircuit) bool {
611		if source.Description != target.Description {
612			return false
613		}
614		if source.Constraints != target.Constraints ||
615			source.PublicInputs != target.PublicInputs ||
616			source.PrivateInputs != target.PrivateInputs {
617			return false
618		}
619		return definitionsEqual(source.Definition, target.Definition, source.PublicInputs, source.PrivateInputs)
620	}
621	
622	// definitionsEqual compares two stored definitions for semantic equality.
623	// Both nil is equal; one nil and the other not is different. When both are
624	// present they are parsed through the existing normalization pipeline and
625	// compared by modulus, constraint count and each side's wire/coefficient
626	// pairs. The public/private layout is the source's; the caller has already
627	// confirmed the counts match.
628	func definitionsEqual(d1, d2 *persistDefinition, public, private int) bool {
629		if d1 == nil && d2 == nil {
630			return true
631		}
632		if d1 == nil || d2 == nil {
633			return false
634		}
635		p1, err := definitionFromPersist(*d1, public, private)
636		if err != nil {
637			return false
638		}
639		p2, err := definitionFromPersist(*d2, public, private)
640		if err != nil {
641			return false
642		}
643		if p1.modulus != p2.modulus || len(p1.constraints) != len(p2.constraints) {
644			return false
645		}
646		for i := range p1.constraints {
647			if !canonicalTermsEqual(p1.constraints[i].a, p2.constraints[i].a) ||
648				!canonicalTermsEqual(p1.constraints[i].b, p2.constraints[i].b) ||
649				!canonicalTermsEqual(p1.constraints[i].c, p2.constraints[i].c) {
650				return false
651			}
652		}
653		return true
654	}
655	
656	// canonicalTermsEqual reports whether two normalized term slices are
657	// identical wire-by-wire and coefficient-by-coefficient.
658	func canonicalTermsEqual(t1, t2 []parsedTerm) bool {
659		if len(t1) != len(t2) {
660			return false
661		}
662		for i := range t1 {
663			if t1[i].wire != t2[i].wire || t1[i].value != t2[i].value {
664				return false
665			}
666		}
667		return true
668	}
669	
670	func setupFromPersist(p persistSetup) Setup {
671		return Setup{Name: p.Name, Version: p.Version}
672	}
673	
674	func jobFromPersist(j persistJob) Job {
675		return Job{
676			ID: j.ID, Circuit: j.Circuit, Version: j.Version,
677			Kind: j.Kind, Attempt: j.Attempt, Artifact: j.Artifact,
678			CompiledHash: j.CompiledHash,
679		}
680	}
681

