138			"{  \"modulus\" : \"7\" ,\n \"constraints\" : [ " +
139				"{ \"a\" : [ {\"wire\":1,\"coeff\":\"1\"} ], \"b\" : [ {\"wire\":2,\"coeff\":\"2\"} ], \"c\" : [ {\"wire\":0,\"coeff\":\"3\"} ] } ] }",
140			// Term order within a side.
141			`{"modulus":"7","constraints":[
142				{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":0,"coeff":"0"},{"wire":2,"coeff":"2"}],"c":[{"wire":0,"coeff":"3"}]}]}`,
143			// Duplicate terms that merge.
144			`{"modulus":"7","constraints":[
145				{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"},{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"3"}]}]}`,
146			// Zero term added.
147			`{"modulus":"7","constraints":[
148				{"a":[{"wire":1,"coeff":"1"},{"wire":2,"coeff":"0"}],"b":[{"wire":2,"coeff":"2"}],"c":[{"wire":0,"coeff":"3"}]}]}`,
149			// Coefficients differing by a multiple of the modulus (7, 14, -7).
150			`{"modulus":"7","constraints":[
151				{"a":[{"wire":1,"coeff":"8"}],"b":[{"wire":2,"coeff":"16"},{"wire":2,"coeff":"-7"}],"c":[{"wire":0,"coeff":"-4"}]}]}`,
152			// A huge coefficient congruent to the small one mod 7 (1 + 7·10^24).
153			`{"modulus":"7","constraints":[
154				{"a":[{"wire":1,"coeff":"7000000000000000000000001"}],"b":[{"wire":2,"coeff":"2"}],"c":[{"wire":0,"coeff":"3"}]}]}`,
155		}
156		for i, v := range variants {
157			if got := hashOfDoc(t, v, "c", 1, 1, 1, 1); got != want {
158				t.Errorf("variant %d changed the hash:\n got %s\nwant %s", i, got, want)
159			}
160		}
