341	func TestCheckInputVerdictsAndGating(t *testing.T) {
342		s := openTestStore(t)
343		// One satisfying constraint 1*2 = 6 mod 7? use pub*priv = c:
344		// wire1 * wire2 = 6, satisfied by (2,3) and (6,1).
345		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
346		if _, err := s.FreezeCircuit("c", 1); err != nil {
347			t.Fatal(err)
348		}
349		artifact, err := s.CompileCircuit("c", 1)
350		if err != nil {
351			t.Fatal(err)
352		}
353	
354		ok := Witness{Public: []string{"2"}, Private: []string{"3"}}
355		res, err := s.CheckInput("c", 1, artifact.Hash, ok)
356		if err != nil || !res.Satisfied || res.FirstFailure != 0 || res.Hash != artifact.Hash {
357			t.Fatalf("satisfied check: %+v %v", res, err)
358		}
359		// Negative and arbitrary-length values interpreted mod p.
360		// -5 ≡ 2 and -4 ≡ 3 mod 7, product 20 ≡ 6.
361		okNeg := Witness{Public: []string{"-5"}, Private: []string{"-4"}}
362		res, err = s.CheckInput("c", 1, artifact.Hash, okNeg)
363		if err != nil || !res.Satisfied {
364			t.Fatalf("negative witness mod p should satisfy: %+v %v", res, err)
365		}
366		// (2 + 7·10^24) · 3 ≡ 6: huge coefficients reduce before evaluation.
367		okBig := Witness{Public: []string{"7000000000000000000000002"}, Private: []string{"3"}}
368		res, err = s.CheckInput("c", 1, artifact.Hash, okBig)
369		if err != nil || !res.Satisfied {
370			t.Fatalf("huge witness mod p should satisfy: %+v %v", res, err)
371		}
372	
373		bad := Witness{Public: []string{"2"}, Private: []string{"4"}} // 2*4=1 != 6
374		res, err = s.CheckInput("c", 1, artifact.Hash, bad)
375		if err != nil {
376			t.Fatal(err)
377		}
378		if res.Satisfied || res.FirstFailure != 1 {
379			t.Fatalf("want unsatisfied first_failure=1, got %+v", res)
380		}
381	
382		// First failing constraint is reported 1-based.
383		two := `{"modulus":"7","constraints":[
384			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"6"}]},
385			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"0"}]}]}`
386		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 3, Constraints: 2,
387			PublicInputs: 1, PrivateInputs: 1, Description: "two"}); err != nil {
388			t.Fatal(err)
389		}
390		if _, err := s.ImportConstraints("c", 3, writeTempJSON(t, two)); err != nil {
391			t.Fatal(err)
392		}
393		s.FreezeCircuit("c", 3)
394		a3, _ := s.CompileCircuit("c", 3)
395		res, err = s.CheckInput("c", 3, a3.Hash, Witness{Public: []string{"2"}, Private: []string{"3"}})
396		if err != nil || res.Satisfied || res.FirstFailure != 2 {
397			t.Fatalf("want first_failure=2, got %+v %v", res, err)
398		}
399	
400		// Gating failures.
401		if _, err := s.CheckInput("ghost", 1, artifact.Hash, ok); !errors.Is(err, ErrNotFound) {
402			t.Fatalf("unknown version: %v", err)
403		}
404		if _, err := s.CreateCircuit(Circuit{Name: "d", Version: 1, Constraints: 1, Description: "d"}); err != nil {
405			t.Fatal(err)
406		}
407		if _, err := s.CheckInput("d", 1, artifact.Hash, ok); !errors.Is(err, ErrNotFrozen) {
408			t.Fatalf("unfrozen: %v", err)
409		}
410		// Frozen but never compiled -> missing artifact.
411		s.FreezeCircuit("d", 1)
412		if _, err := s.CheckInput("d", 1, artifact.Hash, ok); !errors.Is(err, ErrArtifactMissing) {
413			t.Fatalf("missing artifact: %v", err)
414		}
415		// Foreign/wrong hash -> mismatch.
416		if _, err := s.CheckInput("c", 1, artifact.Hash+"00", ok); !errors.Is(err, ErrArtifactMismatch) {
417			t.Fatalf("wrong hash: %v", err)
418		}
419		// Input-format failures never evaluate.
420		for _, w := range []Witness{
421			{Public: []string{}, Private: []string{"3"}},
422			{Public: []string{"2", "x"}, Private: []string{"3"}},
423			{Public: []string{"2"}, Private: []string{"xx"}},
424			{Public: []string{"2"}, Private: []string{}},
425		} {
426			if _, err := s.CheckInput("c", 1, artifact.Hash, w); !errors.Is(err, ErrInvalidInput) {
427				t.Fatalf("want input format error for %+v, got %v", w, err)
428			}
429		}
430	}
