598		res, err := s2.CheckInput("c", 1, a.Hash, Witness{Public: []string{"2"}, Private: []string{"3"}})
599		if err != nil || !res.Satisfied {
600			t.Fatalf("check after reopen: %+v %v", res, err)
601		}
602	}
603	
604	// A tampered stored definition or an artifact inconsistent with its
605	// definition is refused on open like any other read failure.
606	func TestTamperedDefinitionAndArtifactRefused(t *testing.T) {
607		dir := filepath.Join(t.TempDir(), "bench")
608		s, _ := Open(dir)
609		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
610		s.FreezeCircuit("c", 1)
611		if _, err := s.CompileCircuit("c", 1); err != nil {
612			t.Fatal(err)
613		}
614		s.Close()
615		dataFile := filepath.Join(dir, dirDataFile)
616	
617		tamper := func(t *testing.T, mutate func([]byte) []byte) {
618			t.Helper()
619			original, err := os.ReadFile(dataFile)
620			if err != nil {
621				t.Fatal(err)
622			}
623			bad := mutate(append([]byte(nil), original...))
624			if err := os.WriteFile(dataFile, bad, 0o644); err != nil {
625				t.Fatal(err)
626			}
627			if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
628				t.Fatalf("want data corrupt, got %v", err)
629			}
630			// File must be left untouched on refusal.
631			left, _ := os.ReadFile(dataFile)
632			if string(left) != string(bad) {
633				t.Fatal("damaged file was overwritten on refusal")
634			}
635			if err := os.WriteFile(dataFile, original, 0o644); err != nil {
636				t.Fatal(err)
637			}
638		}
639	
640		t.Run("artifact hash", func(t *testing.T) {
641			tamper(t, func(b []byte) []byte {
642				return replaceFirst(b, []byte(`"hash": "`), []byte(`"hash": "deadbeef`))
643			})
644		})
645		t.Run("definition modulus", func(t *testing.T) {
646			tamper(t, func(b []byte) []byte {
647				return replaceFirst(b, []byte(`"modulus": "7"`), []byte(`"modulus": "11"`))
648			})
649		})
650		t.Run("definition coeff", func(t *testing.T) {
651			tamper(t, func(b []byte) []byte {
652				return replaceFirst(b, []byte(`"coeff": "6"`), []byte(`"coeff": "5"`))
653			})
654		})
655		t.Run("artifact count", func(t *testing.T) {
656			tamper(t, func(b []byte) []byte {
657				return replaceFirst(b, []byte(`"constraints": 1,`), []byte(`"constraints": 2,`))
658			})
659		})
660	
661		// After restoring, the directory reads cleanly.
662		if _, err := Open(dir); err != nil {
663			t.Fatalf("restored dir should open: %v", err)
664		}
665	}
666	
667	func replaceFirst(haystack, marker, replacement []byte) []byte {
668		i := indexBytes(haystack, marker)
669		if i < 0 {
670			return haystack
671		}
672		out := append([]byte(nil), haystack[:i]...)
673		out = append(out, replacement...)
674		out = append(out, haystack[i+len(marker):]...)
675		return out
676	}
677	
678	func indexBytes(haystack, needle []byte) int {
679		for i := 0; i+len(needle) <= len(haystack); i++ {
680			if string(haystack[i:i+len(needle)]) == string(needle) {
681				return i
682			}
683		}
684		return -1
685	}
686	
687	// Concurrent import vs freeze must leave only a complete definition (old or
688	// new), never a frozen version with a half-applied or missing definition,
689	// and the on-disk state must reopen consistently.
690	func TestImportFreezeRaceCompleteness(t *testing.T) {
691		for iter := 0; iter < 20; iter++ {
692			dir := t.TempDir()
693			s, _ := Open(dir)
694			seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
695	
696			alt := `{"modulus":"7","constraints":[
697				{"a":[{"wire":1,"coeff":"3"}],"b":[],"c":[]}]}`
698			altPath := writeTempJSON(t, alt)
699	
700			var wg sync.WaitGroup
701			start := make(chan struct{})
702			wg.Add(2)
703			go func() {
704				defer wg.Done()
705				<-start
706				for range 200 {
707					if _, err := s.ImportConstraints("c", 1, altPath); err != nil {
708						if !errors.Is(err, ErrFrozen) {
709							t.Errorf("unexpected import error: %v", err)
710						}
711						return
712					}
713				}
714			}()
715			go func() {
716				defer wg.Done()
717				<-start
718				s.FreezeCircuit("c", 1)
719			}()
720			close(start)
721			wg.Wait()
722	
723			c, err := s.GetCircuit("c", 1)
724			if err != nil {
725				t.Fatal(err)
726			}
727			if !c.Frozen {
728				t.Fatalf("iter %d: version not frozen", iter)
729			}
730			def, err := s.GetDefinition("c", 1)
731			if err != nil {
732				t.Fatalf("iter %d: frozen version must keep a complete definition: %v", iter, err)
733			}
734			// Every import of the same alt content is byte-identical, and the
735			// original is fully distinct: a mixed body is impossible. Just check
736			// the modulus is coherent and it recompiles to a stable hash.
737			a1, err := s.CompileCircuit("c", 1)
738			if err != nil {
739				t.Fatalf("iter %d: compile after race: %v", iter, err)
740			}
741			a2, _ := s.CompileCircuit("c", 1)
742			if a1 != a2 {
743				t.Fatalf("iter %d: artifact not stable: %+v %+v", iter, a1, a2)
744			}
745			if len(def.Constraints) != 1 {
746				t.Fatalf("iter %d: bad definition %+v", iter, def)
747			}
748			s.Close()
749	
750			s2, err := Open(dir)
751			if err != nil {
752				t.Fatalf("iter %d: reopen: %v", iter, err)
753			}
754			got, err := s2.GetArtifact("c", 1)
755			s2.Close()
756			if err != nil || got != a1 {
757				t.Fatalf("iter %d: reopened artifact mismatch: %+v %v", iter, got, err)
758			}
759		}
760	}
761	
762	// ---- witness parsing ------------------------------------------------------
763	
764	func TestParseWitness(t *testing.T) {
765		cases := []struct {
766			name      string
767			doc       string
768			pub, priv int
769			ok        bool
770		}{
771			{"good", `{"public":["1","-2"],"private":["999999999999999999999999"]}`, 2, 1, true},
772			{"empty arrays", `{"public":[],"private":[]}`, 0, 0, true},
773			{"missing public", `{"private":[]}`, 0, 0, false},
774			{"missing private", `{"public":[]}`, 0, 0, false},
775			{"unknown field", `{"public":[],"private":[],"x":1}`, 0, 0, false},
776			{"null public", `{"public":null,"private":[]}`, 0, 0, false},
777			{"public not array", `{"public":1,"private":[]}`, 0, 0, false},
778			{"value number", `{"public":[1],"private":[]}`, 1, 0, false},
779			{"bad value", `{"public":["1.0"],"private":[]}`, 1, 0, false},
780			{"plus value", `{"public":["+1"],"private":[]}`, 1, 0, false},
781			{"garbage", `{bad`, 0, 0, false},
782			{"trailing", `{"public":[],"private":[]} x`, 0, 0, false},
783		}
784		for _, tc := range cases {
785			t.Run(tc.name, func(t *testing.T) {
786				_, err := parseWitness([]byte(tc.doc), tc.pub, tc.priv)
787				if tc.ok && err != nil {
788					t.Fatalf("want ok, got %v", err)
789				}
790				if !tc.ok && !errors.Is(err, ErrInvalidInput) {
791					t.Fatalf("want ErrInvalidInput, got %v", err)
792				}
793			})
794		}
795	}
