					if frozen {
						if _, err := s.FreezeCircuit("c", 1); err != nil {
							t.Fatal(err)
						}
						if _, err := s.CompileCircuit("c", 1); err != nil {
							t.Fatal(err)
						}
					}
					if err := s.Close(); err != nil {
						t.Fatal(err)
					}

