					}
					if s2, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
						if s2 != nil {
							s2.Close()
						}
						t.Fatalf("reopen accepted the damage: %v", err)
					}
				})
			}
		})
	}
}

