	if err != nil {
		return termShape{}, err
	}
	coeffRaw, err := src.shape.require(members, "coeff", what)
	if err != nil {
		return termShape{}, err
	}
	wire, err := src.shape.int(wireRaw, what+" wire")
	if err != nil {
		return termShape{}, err
	}
	coeff, err := src.shape.string(coeffRaw, what+" coefficient")
	if err != nil {
		return termShape{}, err
	}
