5		"encoding/json"
6		"fmt"
7	)
8	
9	// This file is the single source of the structural rules every constraint
10	// definition document follows, on both of its read paths: a JSON file
11	// imported by the user (parseDefinitionJSON in constraints.go) and a
12	// definition already committed in the data directory
13	// (persistDefinition.UnmarshalJSON). The two paths used to each maintain
14	// their own copy of the same three-level shape checks; they now share this
15	// one schema, so the structure they accept can never drift apart.
16	//
17	// The shared rules cover exactly the three-level shape — definition,
18	// constraint, term:
19	//
20	//	definition: an object naming "modulus" and "constraints" exactly once
21	//	constraint: an object naming "a", "b" and "c" exactly once
22	//	term:       an object naming "wire" and "coeff" exactly once
23	//
24	// Every required field must be present and non-null; unknown fields, repeated
25	// fields (including the same field spelled twice through JSON string
26	// escapes, even with identical values) and wrongly typed values are all
27	// rejected. An explicitly empty term array is the zero linear combination and
28	// an explicit wire 0 names the constant wire: both are ordinary values, never
29	// defaults for a missing field.
30	//
31	// The paths differ only in how a structural failure is reported — the import
32	// path rejects the request with ErrInvalidArgument, the committed-data path
33	// refuses the read with ErrDataCorrupt — and in the words each uses to name
34	// the document. Everything else is one rule set. The semantic domain rules
35	// (prime modulus, constraint count, wire layout, coefficient grammar) are
36	// likewise shared: they live in definitionShape.canonicalize and run after
37	// this structural decode on both paths.
38	
39	// jsonShape is the strict-JSON rule set the definition schema is built from:
40	// objects name only allowed keys, required members are present, scalars have
41	// their declared JSON type and no object repeats a key. The fail constructor
42	// tags each rejection with the reading path's error kind; nullSuffix is
43	// appended to object/array null rejections so the committed-data path can
44	// name null explicitly where the import grammar simply rejects the shape.
45	type jsonShape struct {
46		fail       func(format string, args ...any) error
47		nullSuffix string
48	}
49	
50	// object decodes raw as a JSON object whose keys must all be allowed,
51	// rejecting syntax errors, trailing data, duplicates, non-objects and
52	// unknown keys. It returns the raw members for typed decoding.
53	func (s jsonShape) object(raw []byte, allowed []string, what string) (map[string]json.RawMessage, error) {
54		trimmed := bytes.TrimSpace(raw)
55		if string(trimmed) == "null" {
56			return nil, s.fail("%s must be a JSON object%s", what, s.nullSuffix)
57		}
58		if len(trimmed) == 0 || trimmed[0] != '{' {
59			return nil, s.fail("%s must be a JSON object", what)
60		}
61		var members map[string]json.RawMessage
62		if err := json.Unmarshal(trimmed, &members); err != nil {
63			// Unmarshal also rejects trailing data after the top-level value.
64			return nil, s.fail("%s is not valid JSON: %v", what, err)
65		}
66		allowedSet := make(map[string]bool, len(allowed))
67		for _, k := range allowed {
68			allowedSet[k] = true
69		}
70		for key := range members {
71			if !allowedSet[key] {
72				return nil, s.fail("%s has unknown field %q", what, key)
73			}
74		}
75		if err := s.rejectDuplicates(trimmed, what); err != nil {
76			return nil, err
77		}
78		return members, nil
79	}
80	
81	// rejectDuplicates walks the JSON token stream rejecting any object that
82	// names the same key twice; encoding/json silently keeps the last value.
83	// Keys are compared after JSON unescaping, so a key repeated through a
84	// \uXXXX spelling is still a duplicate, even when both values are identical.
85	func (s jsonShape) rejectDuplicates(raw []byte, what string) error {
86		dec := json.NewDecoder(bytes.NewReader(raw))
87		dec.UseNumber()
88		var walk func() error
89		walk = func() error {
90			tok, err := dec.Token()
91			if err != nil {
92				return s.fail("%s is not valid JSON: %v", what, err)
93			}
94			delim, ok := tok.(json.Delim)
95			if !ok {
96				return nil // scalar
97			}
98			switch delim {
99			case '{':
100				seen := make(map[string]bool)
101				for dec.More() {
102					keyTok, err := dec.Token()
103					if err != nil {
104						return s.fail("%s is not valid JSON: %v", what, err)
105					}
106					key := keyTok.(string)
107					if seen[key] {
108						return s.fail("%s contains duplicate field %q", what, key)
109					}
110					seen[key] = true
111					if err := walk(); err != nil {
112						return err
113					}
114				}
115				if _, err := dec.Token(); err != nil { // closing brace
116					return s.fail("%s is not valid JSON: %v", what, err)
117				}
118			case '[':
119				for dec.More() {
120					if err := walk(); err != nil {
121						return err
122					}
123				}
124				if _, err := dec.Token(); err != nil { // closing bracket
125					return s.fail("%s is not valid JSON: %v", what, err)
126				}
127			}
128			return nil
129		}
130		return walk()
131	}
132	
133	// require returns the raw value of a required member.
134	func (s jsonShape) require(members map[string]json.RawMessage, key, what string) (json.RawMessage, error) {
135		raw, ok := members[key]
136		if !ok {
137			return nil, s.fail("%s is missing required field %q", what, key)
138		}
139		return raw, nil
140	}
141	
142	// array requires raw to be a JSON array and returns its raw elements. Null
143	// is rejected: a required array must be provided explicitly, even when empty.
144	func (s jsonShape) array(raw json.RawMessage, what string) ([]json.RawMessage, error) {
145		if string(bytes.TrimSpace(raw)) == "null" {
146			return nil, s.fail("%s must be an array%s", what, s.nullSuffix)
147		}
148		var elements []json.RawMessage
149		if err := json.Unmarshal(raw, &elements); err != nil {
150			return nil, s.fail("%s must be an array: %v", what, err)
151		}
152		return elements, nil
153	}
154	
155	// string requires raw to be a JSON string and returns it.
156	func (s jsonShape) string(raw json.RawMessage, what string) (string, error) {
157		if string(bytes.TrimSpace(raw)) == "null" {
158			return "", s.fail("%s must be a JSON string, not null", what)
159		}
160		var v string
161		if err := json.Unmarshal(raw, &v); err != nil {
162			return "", s.fail("%s must be a JSON string: %v", what, err)
163		}
164		return v, nil
165	}
166	
167	// int requires raw to be a JSON integer (no floats, strings, null).
168	func (s jsonShape) int(raw json.RawMessage, what string) (int, error) {
169		trimmed := bytes.TrimSpace(raw)
170		if string(trimmed) == "null" || len(trimmed) == 0 {
171			return 0, s.fail("%s must be a JSON integer, not null", what)
172		}
173		if trimmed[0] != '-' && (trimmed[0] < '0' || trimmed[0] > '9') {
174			return 0, s.fail("%s must be a JSON integer", what)
175		}
176		var n int
177		if err := json.Unmarshal(raw, &n); err != nil {
178			return 0, s.fail("%s must be a JSON integer: %v", what, err)
179		}
180		return n, nil
181	}
182	
183	// bool requires raw to be a JSON boolean (true/false; not null, a number or
184	// a string).
185	func (s jsonShape) bool(raw json.RawMessage, what string) (bool, error) {
186		trimmed := bytes.TrimSpace(raw)
187		if string(trimmed) == "true" {
188			return true, nil
189		}
190		if string(trimmed) == "false" {
191			return false, nil
192		}
193		if string(trimmed) == "null" || len(trimmed) == 0 {
194			return false, s.fail("%s must be a JSON boolean, not null", what)
195		}
196		return false, s.fail("%s must be a JSON boolean", what)
197	}
198	
199	// ---- the shared three-level definition shape ------------------------------
200	
201	// definitionShape is a constraint definition document after the shared
202	// structural decode and before any domain rule is applied: the modulus text
203	// as written and, for each constraint, its three term arrays.
204	type definitionShape struct {
205		modulus     string
206		constraints []constraintShape
207	}
208	
209	// constraintShape is one structurally decoded {"a":[…],"b":[…],"c":[…]}.
210	type constraintShape struct {
211		a, b, c []termShape
212	}
213	
214	// termShape is one structurally decoded {"wire":int,"coeff":string}.
215	type termShape struct {
216		wire  int
217		coeff string
218	}
219	
220	// definitionShapeSource carries everything that differs between the two
221	// definition read paths: the error kind failures are tagged with and the
222	// names used to describe the document. The structural rules themselves are
223	// shared verbatim.
224	type definitionShapeSource struct {
225		shape      jsonShape
226		definition string // names the definition object
227		modulus    string // names the modulus field
228		constraint string // names one constraint object
229		// term names one term object, given its side and 0-based position.
230		term func(side string, index int) string
231		// wrapConstraint adds the 1-based constraint position to a failure
232		// inside it; nil leaves the failure unadorned.
233		wrapConstraint func(index int, err error) error
234	}
235	
236	// importDefinitionSource describes a definition document supplied by the
237	// user through the import file: failures reject the request as invalid
238	// arguments, and constraints and terms are named with their positions.
239	var importDefinitionSource = definitionShapeSource{
240		shape:      jsonShape{fail: invalidf},
241		definition: "constraint definition",
242		modulus:    "modulus",
243		constraint: "constraint",
244		term: func(side string, index int) string {
245			return fmt.Sprintf("term %s[%d]", side, index)
246		},
247		wrapConstraint: func(index int, err error) error {
248			return fmt.Errorf("constraint #%d: %w", index+1, err)
249		},
250	}
251	
252	// storedDefinitionSource describes a definition committed in the data file:
253	// the same structural damage is an integrity failure of committed data, so
254	// failures are tagged as data corruption and null is named explicitly.
255	var storedDefinitionSource = definitionShapeSource{
256		shape:      jsonShape{fail: corruptf, nullSuffix: ", not null"},
257		definition: "stored constraint definition",
258		modulus:    "stored modulus",
259		constraint: "stored constraint",
260		term: func(side string, index int) string {
261			return "stored term"
262		},
263	}
264	
265	// decodeDefinitionShape applies the shared structural rules to a raw
266	// definition document: exactly the modulus and constraints fields at the top
267	// level, exactly the a/b/c arrays per constraint and exactly the wire/coeff
268	// pair per term, each present, non-null and correctly typed.
269	func decodeDefinitionShape(raw []byte, src definitionShapeSource) (definitionShape, error) {
270		members, err := src.shape.object(raw, []string{"modulus", "constraints"}, src.definition)
271		if err != nil {
272			return definitionShape{}, err
273		}
274		modulusRaw, err := src.shape.require(members, "modulus", src.definition)
275		if err != nil {
276			return definitionShape{}, err
277		}
278		constraintsRaw, err := src.shape.require(members, "constraints", src.definition)
279		if err != nil {
280			return definitionShape{}, err
281		}
282		modulusText, err := src.shape.string(modulusRaw, src.modulus)
283		if err != nil {
284			return definitionShape{}, err
285		}
286		constraintRaws, err := src.shape.array(constraintsRaw, src.definition+` field "constraints"`)
287		if err != nil {
288			return definitionShape{}, err
289		}
290		out := definitionShape{
291			modulus:     modulusText,
292			constraints: make([]constraintShape, 0, len(constraintRaws)),
293		}
294		for i, craw := range constraintRaws {
295			con, err := decodeConstraintShape(craw, src)
296			if err != nil {
297				if src.wrapConstraint != nil {
298					return definitionShape{}, src.wrapConstraint(i, err)
299				}
300				return definitionShape{}, err
301			}
302			out.constraints = append(out.constraints, con)
303		}
304		return out, nil
305	}
306	
307	// decodeConstraintShape decodes one {"a":[…],"b":[…],"c":[…]} object.
308	func decodeConstraintShape(raw json.RawMessage, src definitionShapeSource) (constraintShape, error) {
309		members, err := src.shape.object(raw, []string{"a", "b", "c"}, src.constraint)
310		if err != nil {
311			return constraintShape{}, err
312		}
313		var out constraintShape
314		for _, side := range []struct {
315			key string
316			dst *[]termShape
317		}{
318			{"a", &out.a}, {"b", &out.b}, {"c", &out.c},
319		} {
320			sideRaw, err := src.shape.require(members, side.key, src.constraint)
321			if err != nil {
322				return constraintShape{}, err
323			}
324			terms, err := decodeTermArray(sideRaw, src, side.key)
325			if err != nil {
326				return constraintShape{}, err
327			}
328			*side.dst = terms
329		}
330		return out, nil
331	}
332	
333	// decodeTermArray decodes one a/b/c side: an explicit array (possibly empty)
334	// of term objects.
335	func decodeTermArray(raw json.RawMessage, src definitionShapeSource, side string) ([]termShape, error) {
336		termRaws, err := src.shape.array(raw, fmt.Sprintf("%s side %q", src.constraint, side))
337		if err != nil {
338			return nil, err
339		}
340		terms := make([]termShape, 0, len(termRaws))
341		for j, traw := range termRaws {
342			term, err := decodeTermShape(traw, src, side, j)
343			if err != nil {
344				return nil, err
345			}
346			terms = append(terms, term)
347		}
348		return terms, nil
349	}
350	
351	// decodeTermShape decodes one {"wire":int,"coeff":string} object.
352	func decodeTermShape(raw json.RawMessage, src definitionShapeSource, side string, index int) (termShape, error) {
353		what := src.term(side, index)
354		members, err := src.shape.object(raw, []string{"wire", "coeff"}, what)
355		if err != nil {
356			return termShape{}, err
357		}
358		wireRaw, err := src.shape.require(members, "wire", what)
359		if err != nil {
360			return termShape{}, err
361		}
362		coeffRaw, err := src.shape.require(members, "coeff", what)
363		if err != nil {
364			return termShape{}, err
365		}
366		wire, err := src.shape.int(wireRaw, what+" wire")
367		if err != nil {
368			return termShape{}, err
369		}
370		coeff, err := src.shape.string(coeffRaw, what+" coefficient")
371		if err != nil {
372			return termShape{}, err
373		}
374		return termShape{wire: wire, coeff: coeff}, nil
375	}
376	
377	// ---- conversions between the shape and the persisted form -----------------
378	
379	// toPersist renders the structural decode in the persisted shape. Empty term
380	// arrays stay explicit empty arrays (never null), matching what the importer
381	// writes.
382	func (s definitionShape) toPersist() persistDefinition {
383		out := persistDefinition{
384			Modulus:     s.modulus,
385			Constraints: make([]persistConstraint, 0, len(s.constraints)),
386		}
387		for _, con := range s.constraints {
388			out.Constraints = append(out.Constraints, persistConstraint{
389				A: termsToPersist(con.a),
390				B: termsToPersist(con.b),
391				C: termsToPersist(con.c),
392			})
393		}
394		return out
395	}
396	
397	func termsToPersist(terms []termShape) []persistTerm {
398		out := make([]persistTerm, 0, len(terms))
399		for _, t := range terms {
400			out = append(out, persistTerm{Wire: t.wire, Coeff: t.coeff})
401		}
402		return out
403	}
404	
405	// shapeFromPersist views an already-decoded stored definition as the shared
406	// structural shape, so the domain rules can re-run without a JSON round
407	// trip.
408	func shapeFromPersist(p persistDefinition) definitionShape {
409		out := definitionShape{
410			modulus:     p.Modulus,
411			constraints: make([]constraintShape, 0, len(p.Constraints)),
412		}
413		for _, con := range p.Constraints {
414			out.constraints = append(out.constraints, constraintShape{
415				a: termsFromPersist(con.A),
416				b: termsFromPersist(con.B),
417				c: termsFromPersist(con.C),
418			})
419		}
420		return out
421	}
422	
423	func termsFromPersist(terms []persistTerm) []termShape {
424		out := make([]termShape, 0, len(terms))
425		for _, t := range terms {
426			out = append(out, termShape{wire: t.Wire, coeff: t.Coeff})
427		}
428		return out
429	}
430	
431	// ---- strict decoding of a persisted definition ----------------------------
432	//
433	// persistDefinition's decoder is the committed-data endpoint of the shared
434	// schema: a stored definition must have exactly the shape the importer
435	// writes, and every shape failure is data corruption, not a bad request.
436	// This runs while the envelope is being read, before validateEnvelope: a
437	// definition that omits a side array or a term's wire/coeff — which a plain
438	// struct decode would silently turn into a nil slice or a zero int/string —
439	// is refused at read time instead of being mistaken for an empty array, wire
440	// 0 or an empty coefficient. An explicitly empty side array still decodes to
441	// the zero linear combination and an explicit wire:0 still names the
442	// constant wire; both are ordinary values and stay legal. The circuit
443	// record's definition pointer itself may be absent or null: encoding/json
444	// leaves the pointer nil without invoking this method, which is exactly the
445	// legacy counts-only state.
446	//
447	// The decoder enforces shape only. The semantic rules (prime modulus, wire
448	// range, constraint count) are re-checked by validateEnvelope through the
449	// same definitionFromPersist pipeline used after a clean import.
450	func (p *persistDefinition) UnmarshalJSON(raw []byte) error {
451		shape, err := decodeDefinitionShape(raw, storedDefinitionSource)
452		if err != nil {
453			return err
454		}
455		*p = shape.toPersist()
456		return nil
457	}
